package com.gestordevendas.api.food; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; public record SnackOrderResponse(UUID id, String clientName, String clientPhone, String clientCity, UUID courierId, String courierName, String itemsText, BigDecimal itemsTotal, BigDecimal deliveryFee, BigDecimal total, BigDecimal costTotal, String kitchenStatus, String paymentStatus, Instant paidAt, PaymentMethod paymentMethod, BigDecimal cashReceived, BigDecimal changeAmount, Instant createdAt){static SnackOrderResponse from(SnackOrder o){return new SnackOrderResponse(o.getId(),o.getClientName(),o.getClientPhone(),o.getClientCity(),o.getCourier()==null?null:o.getCourier().getId(),o.getCourier()==null?null:o.getCourier().getName(),o.getItemsText(),o.getItemsTotal(),o.getDeliveryFee(),o.getTotal(),o.getCostTotal(),o.getKitchenStatus(),o.getPaymentStatus(),o.getPaidAt(),o.getPaymentMethod(),o.getCashReceived(),o.getChangeAmount(),o.getCreatedAt());}}
